const incoming = $input.all();
const root = incoming[0]?.json || {};
const candidates = Array.isArray(root.candidates)
  ? root.candidates
  : incoming.map(item => item.json).filter(item => item?.candidateId);

if (!candidates.length) {
  throw new Error('Fluxo 02 recebeu zero candidatos. Execute o Radar e envie o lote completo.');
}

const chooseLead = (candidate) => {
  if (candidate.creativeLead) return candidate.creativeLead;
  const text = `${candidate.title || ''} ${candidate.snippet || ''}`.toLowerCase();
  if (text.includes('lucia') && text.includes('jason')) return 'lucia_and_jason';
  if (text.includes('lucia')) return 'lucia';
  if (text.includes('jason')) return 'jason';
  return ['technology', 'platforms', 'gameplay'].includes(candidate.topic)
    ? 'jason_or_story_subject'
    : 'story_subject';
};

const disclosure = 'CONCEPT VISUAL — NOT GAMEPLAY';

return candidates.map(candidate => {
  const lead = chooseLead(candidate);
  const claimLabel = candidate.thumbnailTextMode === 'claim_label'
    ? (candidate.topic === 'leak' ? 'LEAK CLAIM' : 'RUMOR')
    : (candidate.official ? 'OFFICIAL' : '');

  const commonImageRules = [
    'original 16:9 YouTube thumbnail background',
    'adult characters only',
    'one clear focal subject, maximum two',
    'high contrast and mobile readability',
    'leave negative space for 2-4 word headline',
    'no text rendered into source image',
    'no nudity or sexual act',
    'no copied screenshot or leaked frame',
    'no logo or fake gameplay UI'
  ].join('; ');

  return {
    json: {
      candidateId: candidate.candidateId,
      editorialStatus: 'needs_verification_and_human_approval',
      candidate,
      creativeBrief: {
        lead,
        claimLabel,
        messageStrategy: 'sell_information_not_body',
        assetOrder: [
          'direct_verified_rockstar_asset',
          'verified_press_asset_with_rights',
          'original_generated_concept'
        ],
        officialGallery: 'https://www.rockstargames.com/VI/media/screenshots',
        thumbnailVariants: [
          {
            type: 'character-led',
            lead,
            imagePrompt: `${commonImageRules}; lead: ${lead}; visually express the verified subject without inventing events`
          },
          {
            type: 'evidence-led',
            lead: 'story_subject',
            imagePrompt: `${commonImageRules}; emphasize the verified location, object, document, vehicle, or announcement`
          },
          {
            type: 'alternate',
            lead: lead === 'lucia' ? 'jason_or_environment' : 'lucia_or_environment',
            imagePrompt: `${commonImageRules}; alternate angle tied directly to the same verified story`
          }
        ],
        generatedVisualDisclosure: disclosure,
        redBeachOutfitFallback:
          'If the verified official Lucia red-bikini asset is unavailable or unconfirmed, use an original non-explicit red beach outfit concept and include the disclosure.'
      },
      editorialPromptFile: 'n8n/prompts/vicescope-editorial-master.md',
      policyFile: 'n8n/vicescope-master-policy.json'
    }
  };
});

const packages = $input.all().map(item => item.json);
return [{
  json: {
    schemaVersion: '2.0',
    status: 'ready_for_editorial_model',
    generatedAt: new Date().toISOString(),
    count: packages.length,
    manualApprovalRequired: true,
    noAutomaticPublishing: true,
    packages
  }
}];

